uint32_t SoundSubsystem::fade_bgm_silence(
    uint32_t channel, uint32_t duration_ms) {
    const uint32_t status = check_bgm(channel);
    if (status != kOk) {
        return status;
    }
    auto& slot = bgm_channels_[channel];
    // 004C25F0 and 004C2590 both replace the +2C envelope ending at +40.
    slot.full_fade = make_fade(slot.full_level, 0, duration_ms);
    slot.silence_fade = {};
    return kOk;
}
